// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  interpolateColors,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');

// Load font at module level
const { fontFamily: antonFamily } = loadAnton();



export type BurningMoneyProps = Record<string, any>;

// Sub-component: Fire Particle System
const FireParticle: React.FC<{
  index: number;
  frame: number;
  fps: number;
  width: number;
  height: number;
  colors: { inner: string; mid: string; outer: string };
}> = ({ index, frame, fps, width, height, colors }) => {
  // Stagger particle creation
  const delay = random(`delay-${index}`) * 45;
  const startFireFrame = 45; // Fire erupts at 1.5s
  const elapsed = frame - startFireFrame - delay;

  if (elapsed < 0) return null;

  // Particle life cycle parameters
  const lifeSpan = fps * 1.5 + random(`life-${index}`) * fps * 1.5;
  const cycle = Math.floor(elapsed / lifeSpan);
  const localFrame = elapsed % lifeSpan;
  const progress = localFrame / lifeSpan;

  // Unique seed per respawn to ensure continuous random generation
  const seed = `${index}-${cycle}`;

  // Position bounds relative to stack center
  const xSpread = random(`x-${seed}`) * 500 - 250;
  const startX = width / 2 + xSpread;
  const startY = height * 0.75 + random(`y-${seed}`) * 60;

  const moveY = 400 + random(`moveY-${seed}`) * 600;
  const y = interpolate(progress, [0, 1], [startY, startY - moveY]);

  // Organic swaying motion
  const swayFreq = 0.05 + random(`swayF-${seed}`) * 0.05;
  const swayAmp = 20 + random(`swayA-${seed}`) * 60;
  const x = startX + Math.sin(elapsed * swayFreq) * swayAmp;

  // Scale: grow rapidly, then expand slowly into smoke
  const maxScale = 0.5 + random(`scale-${seed}`) * 1.5;
  const scale = interpolate(progress, [0, 0.2, 0.8, 1], [0, maxScale, maxScale * 1.2, maxScale * 2]);

  // Rotation
  const rot = interpolate(progress, [0, 1], [random(`rot1-${seed}`) * 90, random(`rot2-${seed}`) * 360]);

  // Color transforms from fire to dark smoke/ash
  const color = interpolateColors(
    progress,
    [0, 0.2, 0.5, 0.8, 1],
    [colors.inner, colors.mid, colors.outer, "#333333", "#111111"]
  );

  const opacity = interpolate(progress, [0, 0.1, 0.6, 1], [0, 0.9, 0.6, 0]);
  const size = 60 + random(`size-${index}`) * 40;

  return (
    <div
      style={{
        position: "absolute",
        width: size,
        height: size,
        left: x - size / 2,
        top: y - size / 2,
        backgroundColor: color,
        borderRadius: random(`shape-${index}`) > 0.5 ? "50%" : "30%",
        transform: `scale(${scale}) rotate(${rot}deg)`,
        opacity: opacity,
        filter: "blur(6px)",
        transition: "none",
        zIndex: 10 + Math.floor(random(`z-${index}`) * 20),
      }}
    />
  );
};

// Sub-component: The Particle Container
const ParticleContainer: React.FC<{
  frame: number;
  fps: number;
  width: number;
  height: number;
  colors: { inner: string; mid: string; outer: string };
  density: number;
}> = ({ frame, fps, width, height, colors, density }) => {
  return (
    <div style={{ position: "absolute", inset: 0, zIndex: 15, pointerEvents: "none" }}>
      {new Array(density).fill(true).map((_, i) => (
        <FireParticle
          key={i}
          index={i}
          frame={frame}
          fps={fps}
          width={width}
          height={height}
          colors={colors}
        />
      ))}
    </div>
  );
};

// Sub-component: The Cartoon Money Stack
const MoneyStack: React.FC<{
  frame: number;
  fps: number;
  width: number;
  height: number;
  mainColor: string;
  bandColor: string;
  stackSize: number;
}> = ({ frame, fps, width, height, mainColor, bandColor, stackSize }) => {
  const billWidth = Math.min(width * 0.7, 600);
  const billHeight = billWidth * 0.45;
  const stackSpacing = 15;

  return (
    <div
      style={{
        position: "absolute",
        left: width / 2 - billWidth / 2,
        top: height * 0.75 - billHeight,
        width: billWidth,
        height: billHeight + stackSize * stackSpacing,
        transition: "none",
        zIndex: 5,
      }}
    >
      {new Array(stackSize).fill(true).map((_, index) => {
        // Drop animation (bottom bill drops first)
        const dropSpring = spring({
          fps,
          frame: frame - index * 3,
          config: { damping: 10, mass: 1.2, stiffness: 100 },
        });

        const yOffset = interpolate(dropSpring, [0, 1], [-height, -index * stackSpacing]);

        // Charring logic starting slightly after fire erupts
        const charProgress = interpolate(
          frame,
          [60 + index * 5, 120 + index * 5],
          [0, 1],
          { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
        );

        const currentMainColor = interpolateColors(charProgress, [0, 1], [mainColor, "#222222"]);
        const currentBandColor = interpolateColors(charProgress, [0, 1], [bandColor, "#111111"]);
        
        // As bills burn, they shrivel and warp slightly
        const burnScale = interpolate(charProgress, [0, 1], [1, 0.95]);
        const baseRotate = interpolate(
          dropSpring,
          [0, 1],
          [random(`rot-${index}`) * 20 - 10, (random(`rotFinal-${index}`) - 0.5) * 6]
        );
        const burnRotate = interpolate(
          charProgress,
          [0, 1],
          [0, (random(`burnRot-${index}`) - 0.5) * 8]
        );
        const finalRotate = baseRotate + burnRotate;

        return (
          <div
            key={index}
            style={{
              position: "absolute",
              bottom: 0,
              width: "100%",
              height: billHeight,
              backgroundColor: currentMainColor,
              borderRadius: 12,
              border: `4px solid ${interpolateColors(charProgress, [0, 1], ["#000000", "#111111"])}`,
              transform: `translateY(${yOffset}px) rotate(${finalRotate}deg) scale(${burnScale})`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "none",
              zIndex: index, // Higher index renders on top
              overflow: "hidden",
            }}
          >
            {/* Currency details - Inner engraving borders */}
            <div
              style={{
                position: "absolute",
                inset: "6%",
                border: `3px solid ${interpolateColors(charProgress, [0, 1], ["#ffffff60", "#444444"])}`,
                borderRadius: 8,
                transition: "none",
                pointerEvents: "none",
              }}
            />

            {/* Money band wrapping around */}
            <div
              style={{
                width: "25%",
                height: "100%",
                backgroundColor: currentBandColor,
                borderLeft: "4px solid #000",
                borderRight: "4px solid #000",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                transition: "none",
                position: "relative",
              }}
            >
              <span
                style={{
                  fontFamily: antonFamily,
                  fontSize: billHeight * 0.45,
                  color: interpolateColors(charProgress, [0, 1], ["#ffffff", "#333333"]),
                  WebkitTextStroke: "2px #000",
                  transform: "rotate(-90deg)",
                  transition: "none",
                }}
              >
                $
              </span>
            </div>
          </div>
        );
      })}
    </div>
  );
};

// Sub-component: Background Glow synchronized with fire
const Glow: React.FC<{
  frame: number;
  height: number;
  width: number;
  fireMidColor: string;
}> = ({ frame, height, width, fireMidColor }) => {
  const fireGlowProgress = interpolate(frame, [45, 90], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const pulse = Math.sin(frame / 6) * 0.1 + 0.9;
  const opacity = fireGlowProgress * pulse * 0.7;

  return (
    <div
      style={{
        position: "absolute",
        left: width / 2 - 400,
        top: height * 0.75 - 400,
        width: 800,
        height: 800,
        background: `radial-gradient(circle, ${fireMidColor} 0%, transparent 70%)`,
        opacity,
        transition: "none",
        zIndex: 1,
        pointerEvents: "none",
      }}
    />
  );
};

// Sub-component: Dropping Title
const Title: React.FC<{
  frame: number;
  fps: number;
  text: string;
  color: string;
}> = ({ frame, fps, text, color }) => {
  if (!text) return null;

  const drop = spring({ fps, frame: frame - 15, config: { damping: 12 } });
  const y = interpolate(drop, [0, 1], [-200, 180]);

  // Simulate fire light flickering on the text
  const flicker = frame > 50 ? interpolate(random(`flick-${frame}`), [0, 1], [0.85, 1]) : 1;
  const fireGlowProgress = interpolate(frame, [45, 90], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const glowOpacity = interpolateColors(
    fireGlowProgress,
    [0, 1],
    ["transparent", "rgba(255, 106, 0, 0.6)"]
  );

  return (
    <div
      style={{
        position: "absolute",
        top: y,
        width: "100%",
        textAlign: "center",
        fontSize: 120,
        fontFamily: antonFamily,
        color: color,
        WebkitTextStroke: "4px #000",
        textShadow: `6px 6px 0px #000, 0 0 30px ${glowOpacity}`,
        opacity: flicker,
        transition: "none",
        zIndex: 20,
        lineHeight: 1.1,
        padding: "0 40px",
      }}
    >
      {text.toUpperCase()}
    </div>
  );
};

// Main Component
const BurningMoney: React.FC<BurningMoneyProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = false,
  durationInSeconds = 8,
  titleText = "BURNING CASH",
  titleColor = "#ffffff",
  moneyMainColor = "#4ade80",
  moneyBandColor = "#166534",
  fireInnerColor = "#ffe600",
  fireMidColor = "#ff6a00",
  fireOuterColor = "#ff0000",
  fireIntensity = 80,
  stackSize = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <Glow frame={frame} height={height} width={width} fireMidColor={fireMidColor} />
      
      <MoneyStack
        frame={frame}
        fps={fps}
        width={width}
        height={height}
        mainColor={moneyMainColor}
        bandColor={moneyBandColor}
        stackSize={stackSize}
      />
      
      <ParticleContainer
        frame={frame}
        fps={fps}
        width={width}
        height={height}
        colors={{ inner: fireInnerColor, mid: fireMidColor, outer: fireOuterColor }}
        density={fireIntensity}
      />
      
      <Title frame={frame} fps={fps} text={titleText} color={titleColor} />
    </AbsoluteFill>
  );
};

export default BurningMoney;